"""Baby 81 storyboard frames (STORIES channel style: STYLE v2 game-engine 3D, prompts/style_zackd_3d_render.md) via Nano Banana 2.1 ($0.02 each, 1K, 9:16).
SB-v1 = STYLE v2 + SCENE LOCK + SHOT DELTA. Text is never generated by the model (our own captions and chips are composited later).
Usage: python3 shots_b81.py s01 s02 ...  (runs two at a time, APIpod rate limit) -> /home/claude/v88/frames/<id>.jpg"""
import os
import subprocess
import sys

LOCK = ("Eastern Sri Lanka (Kalmunai), December 2004, tropical coast, palm trees, whitewashed buildings with red tile roofs. "
        "Characters, keep identical in every shot: BABY: a two-month-old infant swaddled in a pale yellow cotton cloth, dark hair, calm. "
        "MOTHER: about 25, warm brown skin, long black hair in a bun, plain dark-green cotton sari with a thin gold border. "
        "FATHER: about 30, brown skin, short black hair and a moustache, checked sarong and a plain white shirt. "
        "NURSE: about 40, white nurse's uniform sari with a small white cap. "
        "JUDGE: about 55, black judicial robe over a white shirt with a white collar band. "
        "Realistic Sri Lankan Tamil faces, respectful and dignified, no stereotypes, no blood, no dead bodies, no gore. ")
SHOTS = {
    "s01": "Low camera on wet sand at dawn: the swaddled baby lies alone on the sand among scattered debris (broken wooden planks, a torn fishing net, a plastic basin), the calm sea behind, grey-blue cold light with a thin warm line of sun on the horizon, shallow depth of field, close on the baby's calm face. No people.",
    "s02": "Interior of a crowded government hospital corridor with cool blue-green walls: the nurse carries the swaddled baby quickly through a crowd of worried people, camera behind her at shoulder height, motion in the background, tired doctors in white coats.",
    "s03": "A hospital ward with rows of simple iron cots: in the foreground a cot with the swaddled baby sleeping, the nurse in white adjusting the cloth, soft window light, a blank white tag hangs on the cot rail with nothing written on it.",
    "s04": "Hospital reception desk: the mother and father stand in front of a tired doctor in a white coat who shakes his head, the mother's hands are open and empty, her eyes full of tears, the father holds her shoulder, cool blue light, other patients blurred behind.",
    "s04b": "A powerful but not graphic tsunami wave rolling over a small coastal house with a red tile roof and palm trees, spray and debris in the air, bright daylight, cinematic wide shot, no people visible.",
    "s05": "In a hospital doorway several different couples stand close together, each pair looking toward the ward with hopeful tense faces, one woman points inside, the background blurred, faces non-specific, cool light with a warm rim from the doorway.",
    "s06": "A simple Sri Lankan magistrate's courtroom with wooden panelling and ceiling fans: the judge at the raised bench holds a gavel and looks at a document, crowded public benches in front, a flag in the corner, low camera, warm wood tones.",
    "s07": "A small clean laboratory: gloved hands hold a cotton swab near the swaddled baby's cheek while a lab technician in a white coat watches, the baby calm, bright clinical light, blue and white palette, shallow depth of field.",
    "s08": "Close-up on a laboratory bench: a dark monitor glows with abstract glowing blue vertical bars in three columns that look like a DNA band pattern, a gloved hand on a mouse, reflections, moody blue light, no readable text.",
    "s09": "A white hospital van with a police motorcycle escort drives along a coastal road lined with palm trees in the morning, seen from the side, two nurses and a police officer sit inside near the window, soft golden light, the baby not visible.",
    "s10": "Close on the mother's tense face in the courtroom, hands clasped near her mouth, tears in her eyes, the father blurred beside her, warm wood background, shallow depth of field, the judge's bench just visible out of focus.",
    "s11": "In the courtroom the mother takes the swaddled baby from a doctor in a white coat into her arms and presses her face to him, the father hugging both, the crowd softly blurred behind, warm golden light through the windows, emotional wide-medium shot.",
}
G = os.path.join(os.path.dirname(os.path.abspath(__file__)), "gen_frame.py")
if __name__ == "__main__":
    ids = sys.argv[1:]
    for k in range(0, len(ids), 2):
        ps = [(s, subprocess.Popen(["python3", G, f"/home/claude/v88/frames/{s}.jpg", LOCK + SHOTS[s]],
                                   stdout=open(f"/home/claude/v88/frames/{s}.log", "w"), stderr=subprocess.STDOUT)) for s in ids[k:k + 2]]
        for s, p in ps:
            p.wait()
            ok = os.path.exists(f"/home/claude/v88/frames/{s}.jpg") and os.path.getsize(f"/home/claude/v88/frames/{s}.jpg") > 30000
            print(s, "ok" if ok else "FAIL", flush=True)
